const uid = (msg.payload.uid || '').trim().toLowerCase();
const pwd = (msg.payload.pwd || '').trim();

const validUsers = {
    'ngoclinh': { pwd: '123456', name: 'Nguyễn Thị Ngọc Linh' },
    'admin': { pwd: '123456', name: 'Quản trị viên Hệ thống' },
    'duycop': { pwd: '123456', name: 'Thầy Đỗ Duy Cợp' }
};

if (validUsers[uid] && validUsers[uid].pwd === pwd) {
    const generatedCk = 'session_' + Math.random().toString(36).substring(2) + Date.now();
    msg.payload = {
        ok: 1,
        msg: 'Đăng nhập thành công!',
        uid: uid,
        fullname: validUsers[uid].name,
        ck: generatedCk
    };
} else {
    msg.payload = {
        ok: 0,
        msg: 'Sai tài khoản hoặc mật khẩu! Vui lòng thử lại.'
    };
}
return msg;

const ck = msg.payload.ck;
if (ck && typeof ck === 'string' && ck.startsWith('session_')) {
    msg.payload = { ok: 1, msg: 'Phiên đăng nhập hợp lệ!' };
} else {
    msg.payload = { ok: 0, msg: 'Phiên làm việc hết hạn hoặc không tồn tại.' };
}
return msg;

